mapper.select:
SELECT a.ID AS value,a.platfrom_name AS label FROM system_docking.api_interface_system_platform_info a LEFT JOIN system_docking.api_interface_system_info b ON a.system_id=b.ID WHERE a.is_enable='1' AND b.is_enable='1'
AND b.system_code =#{params.systemType}
AND EXISTS (SELECT DISTINCT c.platform_id FROM system_docking.api_platform_index_info c WHERE c.is_enable='1' AND c.is_monitor='${params.is_monitor}' AND a.ID=c.platform_id)

SELECT a.ID AS value,a.index_name AS label FROM system_docking.api_platform_index_info a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.ID LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.ID WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1' and a.is_monitor='0' AND c.system_code='ucloud'
AND a.platform_id=#{params.platform}
ORDER BY index_name

SELECT a.ID AS value,a.index_name AS label FROM system_docking.api_platform_index_info a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.ID LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.ID WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1' AND c.system_code='upm'
AND a.platform_id=#{params.platform}
ORDER BY index_name

SELECT DISTINCT a.ID AS value,CONCAT(a.resource_desc,'(',f.ip_address,')') AS label FROM system_docking.api_system_resource a LEFT JOIN system_docking.api_system_index_resource b ON a.ID=b.resource_id LEFT JOIN system_docking.api_platform_index_info c ON b.index_id=c.ID LEFT JOIN system_docking.api_interface_system_platform_info d ON c.platform_id=d.ID LEFT JOIN system_docking.api_interface_system_info e ON d.system_id=e.ID LEFT JOIN system_docking.api_system_resource_ip f ON a.ID=f.resource_id WHERE a.is_enable='1' AND c.is_enable='1' AND d.is_enable='1' AND e.is_enable='1' AND e.system_code = 'ucloud'
AND c.ID=#{params.indicators}
ORDER BY label

SELECT DISTINCT a.resource_code AS value,a.resource_desc AS label FROM system_docking.api_system_resource a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.ID LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.ID WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1' AND c.system_code='upm'
AND b.ID=#{params.platform}
ORDER BY label
